/* v0.2: compact workspace and explicitly simulated laboratory integration. */
let patientTab='Summary',page=0;const perPage=8;state.results??=[];state.labReviews??={};
const oldDetail=detail,oldIntegration=integration;
const TABS=['Summary','Laboratory','Cultures','Vitals & trends','Care checklist'];
function latestResults(pid){const map=new Map();for(const r of state.results.filter(r=>r.patientId===pid)){const k=r.accession+'|'+r.code;const old=map.get(k);if(!old||new Date(r.issuedAt)>new Date(old.issuedAt))map.set(k,r)}return [...map.values()].sort((a,b)=>new Date(b.observedAt)-new Date(a.observedAt))}
function labAlerts(pid){const seen=new Set();return latestResults(pid).filter(r=>{if(r.code==='culture')return true;if(seen.has(r.code))return false;seen.add(r.code);return true}).filter(r=>r.status!=='cancelled'&&(r.critical||r.code==='culture'&&r.value==='Positive'||r.code==='temperature'&&r.unit==='°C'&&r.value>=38.3||r.code==='ANC'&&r.unit==='×10⁹/L'&&r.value<0.5));}
function overview(){const high=patients.filter(p=>assess(p).risk==='High').length,rows=patients.filter(p=>JSON.stringify([id(p),p.Diagnosis,patientName(p)]).toLowerCase().includes(search.toLowerCase())&&(filter==='All'||assess(p).risk===filter));page=Math.min(page,Math.max(0,Math.ceil(rows.length/perPage)-1));return header('Clinical workspace','A focused view of your patients. Details when you need them.',`<button class="btn primary" onclick="go('Integration')">Result inbox ↗</button>`)+`<div class="metricgrid">${metricCard('patients','Patient registry',patients.length,'View all synthetic cases','All','slate')}${metricCard('shield','High-risk pathway',high,'Review high-risk patients','High','coral')}${metricCard('heart','Low-risk pathway',patients.length-high,'Review low-risk patients','Low','mint')}${metricCard('lab','Result events',state.results.length,'Open results & review queue','results','blue')}</div><button class="connectioncard" onclick="openConnection()">${uiIcon('link')}<span><strong>Integration workspace</strong><small>Simulation mode · configure and test the result workflow</small></span><span class="connectionstatus">Not connected</span>${uiIcon('arrow')}</button><div class="panel"><div class="sectiontitle"><h2>Patient list</h2><span class="tag">Excel cohort · 8 per page</span></div><div class="tools"><input id="search" aria-label="Search patients" placeholder="Find a patient ID or diagnosis…" value="${esc(search)}" oninput="search=this.value;page=0;refreshRows()"><select aria-label="Risk filter" onchange="filter=this.value;page=0;render()"><option ${filter==='All'?'selected':''}>All</option><option ${filter==='High'?'selected':''}>High</option><option ${filter==='Low'?'selected':''}>Low</option></select></div><div id="rows">${compactRows(rows)}</div></div><div class="quietnote">Synthetic educational workspace. Clinical rules are draft; no medication orders are transmitted.</div>`}
function compactRows(rows){let pages=Math.max(1,Math.ceil(rows.length/perPage));return table(rows.slice(page*perPage,(page+1)*perPage))+`<div class="pagination"><span>${rows.length} matches · Page ${page+1} of ${pages}</span><div><button class="btn" ${page===0?'disabled':''} onclick="page--;render()">← Previous</button> <button class="btn" ${page>=pages-1?'disabled':''} onclick="page++;render()">Next →</button></div></div>`}
refreshRows=function(){const rows=patients.filter(p=>JSON.stringify([id(p),p.Diagnosis,patientName(p)]).toLowerCase().includes(search.toLowerCase())&&(filter==='All'||assess(p).risk===filter));$('#rows').innerHTML=compactRows(rows)};
openPatient=function(pid){selected=patients.find(p=>id(p)===pid);patientTab='Summary';go('Patient assessment')};
function changeTab(t){patientTab=t;render()}
function detail(){if(!selected)return header('Patient assessment','Choose a case from the patient list.')+`<button class="btn primary" onclick="go('Overview')">Browse patients</button>`;const p=selected,pid=id(p),a=assess(p),results=latestResults(pid),alerts=labAlerts(pid);let html=header(pid+' · '+esc(p.Diagnosis),p['Age (years)']+' years · '+esc(p['Cancer category']),`<button class="btn" onclick="go('Overview')">← Patients</button>`)+`<div class="patientbar"><span>Workbook baseline ${badge(a.risk)}</span><span>MASCC <b>${a.score}/26</b></span><button class="allergy actionchip" onclick="openAllergy()">${allergyLabel(pid)} ${uiIcon('arrow')}</button><span>${results.length?'Simulated results available':'No result feed for this case'}</span></div><div class="tabs">${TABS.map(t=>`<button class="${patientTab===t?'selected':''}" onclick="changeTab('${t}')">${t}${t==='Laboratory'&&alerts.length?` <span class="count">${alerts.length}</span>`:''}</button>`).join('')}</div>`;
if(patientTab==='Summary')html+=`<div class="grid2"><section class="panel"><h2>Clinical snapshot</h2><div class="snapshot">${[['Temperature',p['Temp (°C)']+' °C'],['ANC',p['ANC (×10⁹/L)']+' ×10⁹/L'],['Blood pressure',p['Systolic BP (mmHg)']+' systolic'],['Renal function',p['CrCl (mL/min)']+' mL/min CrCl']].map(([k,v])=>`<div><small>${k}</small><strong>${v}</strong><span>Workbook · time not supplied</span></div>`).join('')}</div><details><summary>Why this pathway?</summary><p>MASCC ${a.score}. ${a.flags.length?esc(a.flags.join('; ')):'No additional high-risk flags in supplied fields.'}</p><p>Imported classification remains separate from new simulated observations. A fresh clinical assessment is required after new results.</p></details></section><section class="panel"><h2>Review priorities</h2>${alerts.length?alerts.slice(0,3).map(alertCard).join(''):`<p>No result-triggered alerts yet. Missing results do not mean normal results.</p><button class="btn primary" onclick="changeTab('Laboratory')">Open laboratory view →</button>`}<div class="quietnote">Allergy status and medication rules require review. No clinical order engine is enabled.</div></section></div>`;
if(patientTab==='Laboratory')html+=`<section class="panel"><div class="sectiontitle"><div><h2>Laboratory results</h2><p>Workbook values and simulated incoming results are kept separate.</p></div><button class="btn primary" onclick="seedResults()">Run demo result feed</button></div>${results.length?resultTable(results.filter(r=>r.code!=='culture'&&!['temperature','systolicBP','heartRate','SpO2'].includes(r.code))):'<div class="empty">No timestamped laboratory results imported. Use the demo feed to test the workflow.</div>'}<details><summary>Imported baseline · no collection timestamps</summary><p>ANC: ${p['ANC (×10⁹/L)']} ×10⁹/L · CrCl: ${p['CrCl (mL/min)']} mL/min · Other CBC, CRP, lactate and renal analytes are not supplied.</p></details><div class="quietnote">Demo-generated results do not represent additional measurements from the original Excel file.</div></section>${alerts.length?`<section class="panel" style="margin-top:18px"><h2>Result-linked alerts</h2>${alerts.map(alertCard).join('')}</section>`:''}`;
if(patientTab==='Cultures'){const cultures=results.filter(r=>r.code==='culture');html+=`<section class="panel"><div class="sectiontitle"><div><h2>Microbiology & cultures</h2><p>Accession, specimen, collection time, report status and susceptibility.</p></div><button class="btn" onclick="seedResults()">Load demo culture</button></div>${cultures.length?cultures.map(r=>`<div class="culturecard"><div class="sectiontitle"><h3>${esc(r.specimen)} · ${esc(r.accession)}</h3><span class="pill ${r.value==='Positive'?'red':''}">${esc(r.status)} · ${esc(r.value)}</span></div><p><b>${esc(r.organism||'Organism not reported')}</b> · Source: ${esc(r.source)}</p><p>Collected: ${r.collectionTimeUnknown?'Not documented in fixture':fmt(r.observedAt)} · Issued: ${fmt(r.issuedAt)}</p>${r.reportText?`<p>${esc(r.reportText)}</p>`:''}${r.susceptibilities?.length?`<table><thead><tr><th>Antimicrobial</th><th>Reported interpretation</th></tr></thead><tbody>${r.susceptibilities.map(s=>`<tr><td>${esc(s.agent)}</td><td>${esc(s.interpretation)}</td></tr>`).join('')}</tbody></table>`:'<p>Identification / susceptibility pending or unavailable.</p>'}${r.value==='Positive'?alertCard(r):''}</div>`).join(''):'<div class="empty">No culture results in the workbook. No negative culture status is assumed.</div>'}<div class="quietnote">Susceptibility is displayed as reported. No antimicrobial selection or dose is inferred.</div></section>`}
if(patientTab==='Vitals & trends'){const temps=results.filter(r=>r.code==='temperature').sort((a,b)=>new Date(a.observedAt)-new Date(b.observedAt));html+=`<section class="panel"><div class="sectiontitle"><div><h2>Temperature & vital signs</h2><p>Timestamped demo observations; no background monitoring.</p></div><button class="btn" onclick="seedResults()">Load demo observations</button></div>${temps.length?`<div class="trendcards">${temps.map(r=>`<div class="trendpoint"><span>${fmt(r.observedAt)}</span><b>${r.value} °C</b><div class="therm" style="height:${Math.max(15,(r.value-36)*28)}px"></div><small>${esc(r.method||'Method unknown')}</small></div>`).join('')}</div>`:'<div class="empty">No timestamped temperature series available.</div>'}${resultTable(results.filter(r=>['temperature','systolicBP','heartRate','SpO2'].includes(r.code)))}</section>`}
if(patientTab==='Care checklist')html+=careChecklistView();return html}
function fmt(t){if(!t)return 'Time not supplied';return new Date(t).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}
function resultTable(rows){if(!rows.length)return '<p>No results in this category.</p>';return `<div class="scroll"><table><thead><tr><th>Test</th><th>Result</th><th>Observed</th><th>Report / provenance</th><th>Review</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.code)}</b></td><td>${esc(r.value)} ${esc(r.unit||'')} ${r.critical?'<span class="pill red">Lab flagged</span>':''}</td><td>${fmt(r.observedAt)}</td><td>${esc(r.status)}<div class="mini">${esc(r.source)} · ${esc(r.accession)}</div></td><td><button class="btn" onclick="reviewResult('${r.eventId}')">${state.labReviews[r.eventId]?'Reviewed':'Review'}</button></td></tr>`).join('')}</tbody></table></div>`}
function alertCard(r){const reviewed=state.labReviews[r.eventId];return `<div class="resultalert"><div><b>${r.code==='culture'?'Positive culture':esc(r.code)+' result requires review'}</b><p>${esc(r.value)} ${esc(r.unit||'')} · ${esc(r.status)} · SIMULATED</p></div><button class="btn" onclick="reviewResult('${r.eventId}')">${reviewed?'Reviewed':'Record review'}</button></div>`}
function reviewResult(eid){state.labReviews[eid]=new Date().toISOString();save('Simulated result review documented: '+eid,selected?id(selected):'Inbox')}
function seedResults(){if(!selected)return;const pid=id(selected);if(state.results.some(r=>r.patientId===pid&&r.source==='Demo generator')){render();return}let t=Date.now(),iso=m=>new Date(t+m*60000).toISOString();const make=(key,code,value,unit,extra={})=>({eventId:pid+'-demo-'+key,patientId:pid,accession:pid+'-DEMO-'+key,code,value,unit,observedAt:iso(-60),issuedAt:iso(-10),status:'final',source:'Demo generator',...extra});state.results.push(make('anc','ANC',selected['ANC (×10⁹/L)'],'×10⁹/L'),make('crp','CRP',84,'mg/L'),make('creat','Creatinine',1.1,'mg/dL'),make('culture','culture','Positive','',{status:'preliminary',specimen:'Blood · peripheral',organism:'Gram-negative bacilli; identification pending',critical:true}),make('temp1','temperature',38.1,'°C',{observedAt:iso(-120),method:'Oral'}),make('temp2','temperature',38.5,'°C',{observedAt:iso(-60),method:'Oral'}),make('temp3','temperature',38.8,'°C',{observedAt:iso(-15),method:'Oral'}));save('Loaded explicitly synthetic lab/culture/vitals scenario',pid)}
let resultPatientFilter='',resultSearch='';
function matchesResultPatient(r){const p=patients.find(p=>id(p)===r.patientId);return (!resultPatientFilter||resultPatientFilter==='__action__'? !resultPatientFilter||!!p?._actionCaseId:r.patientId===resultPatientFilter)&&JSON.stringify([r.patientId,p&&patientName(p),r.code,r.organism,r.value]).toLowerCase().includes(resultSearch.toLowerCase())}
function integration(){const allAlerts=patients.flatMap(p=>labAlerts(id(p)));const inboxRows=(inboxMode==='all'?state.results:allAlerts.filter(r=>!state.labReviews[r.eventId])).filter(matchesResultPatient);return header('Result inbox & integration','Test the complete result-to-review workflow without implying a live connection.',`<button class="btn" onclick="download('fn-result-example.json',exampleResults())">Download JSON template</button>`)+`<div class="compactstats"><span class="pill amber">SIMULATION / FILE IMPORT</span><span><b>${state.results.length}</b> received events</span><span><b>${allAlerts.filter(r=>!state.labReviews[r.eventId]).length}</b> unreviewed flagged results</span><span>No LIS / EHR endpoint connected</span></div><section class="panel" style="margin-bottom:20px"><h2>Patient-matched results</h2><p>The 20 named assessment cases share the same patient IDs as the Overview registry. Fictional results follow each case's simulation clock.</p><div class="tools result-filters"><label class="field">Result patient<select id="resultPatientFilter" onchange="resultPatientFilter=this.value;inboxMode='all';render()"><option value="">All patients</option><option value="__action__" ${resultPatientFilter==='__action__'?'selected':''}>20 assessment-to-action cases</option>${patients.map(p=>`<option value="${id(p)}" ${resultPatientFilter===id(p)?'selected':''}>${esc(patientName(p))} · ${id(p)}</option>`).join('')}</select></label><label class="field">Search results<input id="resultSearch" value="${esc(resultSearch)}" placeholder="Name, patient ID, test or organism" onchange="resultSearch=this.value;render()"></label></div><p>${inboxRows.length} matching events · ${inboxMode==='all'?'All received results':'Needs review queue'}</p></section><div class="grid2"><section class="panel"><h2>Import a simulated result feed</h2><p>JSON import validates patient identity, result codes, units, timestamps, report status and duplicate event IDs. Never upload real patient data.</p><label class="btn primary" style="display:inline-block;cursor:pointer">Choose synthetic JSON<input type="file" accept="application/json,.json" style="display:none" onchange="importResults(this.files[0])"></label><p id="importMessage" role="status" style="margin-top:15px"></p><details><summary>Supported result types</summary><p>ANC, WBC, Hemoglobin, Platelets, CRP, Creatinine, CrCl, Lactate, temperature, systolicBP, heartRate, SpO2 and culture. Reference intervals and critical flags come from the source; institution-specific critical limits are not invented.</p></details></section><section class="panel"><h2>Connection readiness</h2><div class="stage">✓ Patient-matched event import</div><div class="stage">✓ Preliminary / final / corrected status</div><div class="stage">✓ Same-accession correction handling</div><div class="stage">✓ Contextual result review + local audit</div><div class="stage">○ Authenticated LIS / HL7 / FHIR connector</div><div class="stage">○ Server-side escalation and acknowledgment</div><p>Real integration requires the hospital endpoint, authorization, interface specifications and test environment.</p></section></div><section class="panel" style="margin-top:20px"><div class="sectiontitle"><h2>${inboxMode==='all'?'All received result events':'Results needing review'}</h2><div class="segmented"><button class="btn ${inboxMode==='pending'?'primary':''}" onclick="setInbox('pending')">Needs review</button><button class="btn ${inboxMode==='all'?'primary':''}" onclick="setInbox('all')">All events</button></div></div>${inboxRows.length?inboxRows.map(r=>`<div class="resultalert"><div><b>${esc(patientName(patients.find(p=>id(p)===r.patientId)||{'Patient ID':r.patientId}))} · ${esc(r.patientId)} · ${esc(r.code)}</b><p>${esc(r.value)} ${esc(r.unit||'')} · ${esc(r.status)}${r.reportText?' · '+esc(r.reportText):''} · ${state.labReviews[r.eventId]?'Reviewed':'Awaiting review'}</p></div><button class="btn" onclick="openPatient('${r.patientId}');changeTab('${r.code==='culture'?'Cultures':['temperature','systolicBP','heartRate','SpO2'].includes(r.code)?'Vitals & trends':'Laboratory'}')">Open patient →</button></div>`).join(''):'<div class="empty">No results in this queue. <button class="btn" onclick="openDemoPatient()">Open a demo patient →</button></div>'}</section>`}
function exampleResults(){return [{eventId:'example-FN001-anc-1',patientId:'FN-001',accession:'DEMO-ANC-001',code:'ANC',value:0.2,unit:'×10⁹/L',observedAt:new Date().toISOString(),issuedAt:new Date().toISOString(),status:'final',source:'Synthetic file example'}]}
const units={ANC:'×10⁹/L',WBC:'×10⁹/L',Hemoglobin:'g/dL',Platelets:'×10⁹/L',CRP:'mg/L',Creatinine:'mg/dL',CrCl:'mL/min',Sodium:'mmol/L',Potassium:'mmol/L',ALT:'U/L',Bilirubin:'mg/dL',PreviousCreatinine:'mg/dL',UrineWBC:'cells/HPF',Galactomannan:'index; lab-specific interpretation',Lactate:'mmol/L',temperature:'°C',systolicBP:'mmHg',heartRate:'bpm',SpO2:'%'};
function validateResults(arr,known,existing=[]){if(!Array.isArray(arr)||!arr.length||arr.length>1000)throw Error('Supply 1–1000 result events.');const seen=new Set(existing.map(r=>r.eventId));for(const r of arr){if(!r||typeof r!=='object')throw Error('Invalid result object');for(const k of ['eventId','patientId','accession','code','source'])if(typeof r[k]!=='string'||!r[k].trim()||r[k].length>150)throw Error('Invalid '+k);if(!known.includes(r.patientId))throw Error('Unknown patient ID: '+r.patientId);if(seen.has(r.eventId))throw Error('Duplicate event ID: '+r.eventId);seen.add(r.eventId);if(!['preliminary','final','corrected','cancelled'].includes(r.status))throw Error('Invalid report status');if(!Number.isFinite(Date.parse(r.observedAt))||!Number.isFinite(Date.parse(r.issuedAt))||Date.parse(r.issuedAt)<Date.parse(r.observedAt))throw Error('Invalid observation / issue timestamps');if(r.critical!==undefined&&typeof r.critical!=='boolean')throw Error('critical must be boolean');if(r.code==='culture'){if(!['Positive','Negative','Pending','Indeterminate'].includes(r.value)||typeof r.specimen!=='string')throw Error('Invalid culture result');if(r.susceptibilities!==undefined&&(!Array.isArray(r.susceptibilities)||r.susceptibilities.some(s=>typeof s.agent!=='string'||!['S','I','R','Not reported'].includes(s.interpretation))))throw Error('Invalid susceptibility');}else{if(!(r.code in units)||r.unit!==units[r.code]||typeof r.value!=='number'||!Number.isFinite(r.value)||r.value<0)throw Error('Invalid code, value or unit: '+r.code)}}return arr}
async function importResults(file){if(!file)return;try{if(file.size>2000000)throw Error('Maximum file size: 2 MB');const arr=validateResults(JSON.parse(await file.text()),patients.map(id),state.results);state.results.push(...arr);save('Imported '+arr.length+' synthetic result events');$('#importMessage').textContent='Imported '+arr.length+' events. No live connection established.'}catch(e){$('#importMessage').textContent='Import rejected: '+e.message}}
